import{_ as n,a0 as p,w as o,s as r,I as i,x as e,a1 as t,A as l,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const v=JSON.parse('{"title":"管理你的 shell 環境 | LCTT x X-CMD","titleTemplate":false,"description":"管理你的 shell 環境 | LCTT (201907) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"管理你的 shell 環境 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"管理你的 shell 環境 | LCTT (201907) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201907/20190705 Manage your shell environment","title":"管理你的 shell 環境","tag":"201907","desc":""},"relativePath":"201907/20190705 Manage your shell environment.md","filePath":"[post].md"}'),h={name:"201907/20190705 Manage your shell environment.md"};function g(u,s,b,k,c,f){const a=p("Link");return o(),r("div",null,[s[18]||(s[18]=i("h1",{id:"管理你的-shell-環境",tabindex:"-1"},[e("管理你的 shell 環境 "),i("a",{class:"header-anchor",href:"#管理你的-shell-環境","aria-label":"Permalink to “管理你的 shell 環境”"},"​")],-1)),s[19]||(s[19]=i("p",null,[i("img",{src:"https://fedoramagazine.org/wp-content/uploads/2018/05/manage-shell-env-816x345.jpg",alt:""})],-1)),i("p",null,[s[1]||(s[1]=e("前段時間，Fedora Magazine 發表了一篇 ",-1)),t(a,{href:"https://fedoramagazine.org/set-zsh-fedora-system/"},{default:l(()=>[...s[0]||(s[0]=[e("介紹 ZSH",-1)])]),_:1}),s[2]||(s[2]=e(" 的文章，它是 Fedora 默認的 bash shell 的替代品。這一次，我們將着重定製它來更有效地使用它。本文中顯示的所有概念也適用於其他 shell，例如 bash。",-1))]),s[20]||(s[20]=d(`<h3 id="別名" tabindex="-1">別名 <a class="header-anchor" href="#別名" aria-label="Permalink to “別名”">​</a></h3><p>別名是命令的快捷方式。為那些需要經常執行，但需要很長時間輸入的長命令創建快捷方式很有用。語法是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ alias yourAlias=&#39;complex command with arguments&#39;</span></span></code></pre></div><p>它們並不總是用來縮短長命令。重要的是，你將它們用於你經常執行的任務。可能的例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ alias dnfUpgrade=&#39;dnf -y upgrade&#39;</span></span></code></pre></div><p>這樣，為了進行系統升級，我只需輸入 <code>dnfUpgrade</code> 而不用輸入完整的 <code>dnf</code> 命令。</p><p>在終端中設置別名的問題是，一旦終端會話關閉，別名就會丟失。要永久設置它們，請使用資源文件。</p><h3 id="資源文件" tabindex="-1">資源文件 <a class="header-anchor" href="#資源文件" aria-label="Permalink to “資源文件”">​</a></h3><p>資源文件（即 rc 文件）是在會話或進程開始時（每個用户在開啓新終端窗口或啓動 vim 等新程序時）加載的配置文件。對於 ZSH，資源文件是 <code>.zshrc</code>，對於 bash，它是 <code>.bashrc</code>。</p><p>要使別名成為永久別名，你可以將它們放入資源文件中。你可以使用你選擇的文本編輯器編輯資源文件。這裏使用 vim：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vim $HOME/.zshrc</span></span></code></pre></div><p>或者對於 bash：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vim $HOME/.bashrc</span></span></code></pre></div><p>請注意，資源文件的位置是相對於家目錄指定的。這是 ZSH（或 bash）默認為每個用户查找該文件的位置。</p><p>還有一種是將你的配置放在任何其他文件中，然後讀取它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ source /path/to/your/rc/file</span></span></code></pre></div><p>同樣，在會話中直接讀取它只會將其應用於會話，因此要使其永久化，請將 <code>source</code> 命令添加到資源文件中。將文件放在不同位置的優點是你可以隨時讀取它。這在共享環境中很有用。</p><h3 id="環境變量" tabindex="-1">環境變量 <a class="header-anchor" href="#環境變量" aria-label="Permalink to “環境變量”">​</a></h3><p>環境變量是分配了特定名稱的值，你可以在腳本和命令中調用它們。它們以美元符號（<code>$</code>）開始。其中最常見的是指向主目錄的 <code>$HOME</code>。</p><p>顧名思義，環境變量是你環境的一部分。使用以下語法設置變量：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ http_proxy=&quot;http://your.proxy&quot;</span></span></code></pre></div><p>要使其成為環境變量，請使用以下命令將其導出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ export $http_proxy</span></span></code></pre></div><p>要查看當前設置的所有環境變量，請使用 <code>env</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ env</span></span></code></pre></div><p>該命令輸出會話中可用的所有變量。要演示如何在命令中使用它們，請嘗試運行以下 <code>echo</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo $PWD</span></span>
<span class="line"><span>/home/fedora</span></span>
<span class="line"><span>$ echo $USER</span></span>
<span class="line"><span>fedora</span></span></code></pre></div><p>這裏發生了變量擴展，即存儲在變量中的值在命令中使用。</p><p>另一個有用的變量是 <code>$PATH</code>，它定義了 shell 查找二進制文件的目錄。</p><h3 id="path-變量" tabindex="-1">$PATH 變量 <a class="header-anchor" href="#path-變量" aria-label="Permalink to “$PATH 變量”">​</a></h3><p>有許多對於操作系統很重要的目錄或文件夾（在圖形環境中調用它們的方式）。某些目錄設置為保存可直接在 shell 中使用的二進制文件。這些目錄在 <code>$PATH</code> 變量中定義。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo $PATH</span></span>
<span class="line"><span>/usr/lib64/qt-3.3/bin:/usr/share/Modules/bin:/usr/lib64/ccache:/usr/local/bin:/usr/bin:/bin:/usr/local/sbin:/usr/sbin:/usr/libexec/sdcc:/usr/libexec/sdcc:/usr/bin:/bin:/sbin:/usr/sbin:/opt/FortiClient</span></span></code></pre></div><p>當你希望在 shell 中訪問自己的二進制文件（或腳本）時，這會有幫助。</p><hr>`,34)),i("p",null,[s[4]||(s[4]=e("via: ",-1)),t(a,{href:"https://fedoramagazine.org/manage-your-shell-environment/"},{default:l(()=>[...s[3]||(s[3]=[e("https://fedoramagazine.org/manage-your-shell-environment/",-1)])]),_:1})]),i("p",null,[s[9]||(s[9]=e("作者：",-1)),t(a,{href:"https://fedoramagazine.org/author/x3mboy/"},{default:l(()=>[...s[5]||(s[5]=[e("Eduard Lucena",-1)])]),_:1}),s[10]||(s[10]=e(" 選題：",-1)),t(a,{href:"https://github.com/lujun9972"},{default:l(()=>[...s[6]||(s[6]=[e("lujun9972",-1)])]),_:1}),s[11]||(s[11]=e(" 譯者：",-1)),t(a,{href:"https://github.com/geekpi"},{default:l(()=>[...s[7]||(s[7]=[e("geekpi",-1)])]),_:1}),s[12]||(s[12]=e(" 校對：",-1)),t(a,{href:"https://github.com/wxy"},{default:l(()=>[...s[8]||(s[8]=[e("wxy",-1)])]),_:1})]),i("p",null,[s[15]||(s[15]=e("本文由 ",-1)),t(a,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[13]||(s[13]=[e("LCTT",-1)])]),_:1}),s[16]||(s[16]=e(" 原創編譯，",-1)),t(a,{href:"https://linux.cn/"},{default:l(()=>[...s[14]||(s[14]=[e("Linux中國",-1)])]),_:1}),s[17]||(s[17]=e(" 榮譽推出",-1))])])}const x=n(h,[["render",g]]);export{v as __pageData,x as default};
